<script setup lang="ts">import type {Entity} from '../types/domain';defineProps<{modelValue:string,rows:Entity[]}>();defineEmits(['update:modelValue'])</script><template><label>运行记录<select :value="modelValue" @change="$emit('update:modelValue',($event.target as HTMLSelectElement).value)"><option value="">请选择运行</option><option v-for="row in rows" :value="row.id" :key="row.id">{{row.id==='demo-run'?'四站基线':row.id.slice(0,8)}} · {{row.status}}</option></select></label></template>
